```javascript
function sameObject(a, b) {
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  for (const k of keys) {
    if (a[k] !== b[k]) return false;
  }
  return true;
}

function sameArray(a, b) {
  return a.length === b.length && a.every((o, i) => sameObject(o, b[i]));
}
